"use client";

import type { ApiClient } from "@schoolos/api-client";
import { unwrap, useApiQuery, useBffClient } from "@/lib/bff/query";
import type { Loadable } from "@/lib/loadable";

/**
 * School calendar (FT-06; FR-CAL-001..FR-CAL-020) through the BFF. Reads need
 * `student.read_basic`; changes need `tenant.structure.manage`.
 *
 * LOCAL TYPES: the calendar routes are new in this wave and not yet in the generated client
 * (`apps/api/openapi.json` is regenerated by the lead). `calendarApi()` narrows the generated
 * client to an untyped shape for these paths only, and the response types below mirror
 * `app/academics/schemas.py`. After `make openapi`, replace them with
 * `components["schemas"]["CalendarOut" | "CalendarMonthOut" | ...]` and drop `calendarApi()`.
 */

export type CalendarEntryKind = "holiday" | "vacation" | "working_day";
export type CalendarDayKind =
  | "working"
  | "working_day"
  | "weekly_off"
  | "saturday_off"
  | "holiday"
  | "vacation"
  | "outside_year";

export interface CalendarDay {
  on_date: string;
  working: boolean;
  kind: CalendarDayKind;
  name?: string | null;
  entry_id?: string | null;
}

export interface CalendarEntry {
  id: string;
  kind: CalendarEntryKind;
  name: string;
  starts_on: string;
  ends_on: string;
  class_id: string | null;
  suggestion: string | null;
  days: number;
}

export interface CalendarEntryAdded extends CalendarEntry {
  attendance_marks: number;
}

export interface SchoolCalendar {
  academic_year_id: string;
  starts_on: string;
  ends_on: string;
  set_up: boolean;
  weekly_off: number[];
  saturdays_off: number[];
  entries: CalendarEntry[];
  working_days: number | null;
  version: number;
}

export interface CalendarMonth {
  academic_year_id: string;
  month: string;
  class_id: string | null;
  set_up: boolean;
  days: CalendarDay[];
  working_days: number;
}

export interface CalendarSuggestion {
  code: string;
  group: string;
  group_label: string;
  name: string;
  kind: CalendarEntryKind;
  starts_on: string;
  ends_on: string;
}

export interface CalendarSuggestions {
  verified: boolean;
  source: string;
  items: CalendarSuggestion[];
}

export interface CalendarEntryInput {
  kind: CalendarEntryKind;
  name: string;
  starts_on: string;
  ends_on: string;
  class_id: string | null;
  suggestion?: string | null;
}

export const CALENDAR_MANAGE = "tenant.structure.manage";
export const ENTRY_KINDS: readonly CalendarEntryKind[] = ["holiday", "vacation", "working_day"];
/** 0 = Monday .. 6 = Sunday (the API's numbering). */
export const WEEKDAYS = [0, 1, 2, 3, 4, 5, 6] as const;
export const SATURDAY_NUMBERS = [1, 2, 3, 4, 5] as const;

export const SCHOOL_CALENDAR_KEYS = {
  all: ["staff", "school-calendar"] as const,
  year: (yearId: string) => ["staff", "school-calendar", yearId, "year"] as const,
  month: (yearId: string, month: string, classId: string) =>
    ["staff", "school-calendar", yearId, "month", month, classId] as const,
  suggestions: (yearId: string) => ["staff", "school-calendar", yearId, "suggestions"] as const,
};

type Result = Promise<{ data?: unknown; error?: unknown; response: Response }>;
interface Init {
  params?: { path?: Record<string, string>; query?: Record<string, string> };
  headers?: Record<string, string>;
  body?: unknown;
}
interface CalendarClient {
  GET(path: string, init?: Init): Result;
  PUT(path: string, init?: Init): Result;
  POST(path: string, init?: Init): Result;
  DELETE(path: string, init?: Init): Result;
}

/** The generated client, untyped for the calendar paths until the lead regenerates it. */
export function calendarApi(api: ApiClient): CalendarClient {
  return api as unknown as CalendarClient;
}

const YEAR_PATH = "/api/v1/academic-years/{year_id}/calendar";

export function ifMatch(version: number): string {
  return `W/"${version}"`;
}

export async function loadCalendar(api: ApiClient, yearId: string): Promise<SchoolCalendar> {
  return (await unwrap(
    calendarApi(api).GET(YEAR_PATH, { params: { path: { year_id: yearId } } }),
  )) as SchoolCalendar;
}

export async function savePattern(
  api: ApiClient,
  yearId: string,
  version: number,
  pattern: { weekly_off: number[]; saturdays_off: number[] },
): Promise<SchoolCalendar> {
  return (await unwrap(
    calendarApi(api).PUT(YEAR_PATH, {
      params: { path: { year_id: yearId } },
      headers: { "If-Match": ifMatch(version) },
      body: pattern,
    }),
  )) as SchoolCalendar;
}

export async function addEntry(
  api: ApiClient,
  yearId: string,
  body: CalendarEntryInput,
  idempotencyKey: string,
): Promise<CalendarEntryAdded> {
  return (await unwrap(
    calendarApi(api).POST(`${YEAR_PATH}/entries`, {
      params: { path: { year_id: yearId } },
      headers: { "Idempotency-Key": idempotencyKey },
      body,
    }),
  )) as CalendarEntryAdded;
}

export async function removeEntry(api: ApiClient, yearId: string, entryId: string): Promise<null> {
  await unwrap(
    calendarApi(api).DELETE(`${YEAR_PATH}/entries/{entry_id}`, {
      params: { path: { year_id: yearId, entry_id: entryId } },
    }),
  );
  return null;
}

export function useSchoolCalendar(yearId: string | null): Loadable<SchoolCalendar> {
  const api = useBffClient("staff");
  return useApiQuery(
    SCHOOL_CALENDAR_KEYS.year(yearId ?? ""),
    () => loadCalendar(api, yearId ?? ""),
    {
      enabled: yearId !== null,
    },
  );
}

export function useCalendarMonth(
  yearId: string | null,
  month: string,
  classId: string,
): Loadable<CalendarMonth> {
  const api = useBffClient("staff");
  return useApiQuery(
    SCHOOL_CALENDAR_KEYS.month(yearId ?? "", month, classId),
    async () =>
      (await unwrap(
        calendarApi(api).GET(`${YEAR_PATH}/month`, {
          params: {
            path: { year_id: yearId ?? "" },
            query: classId ? { month, class_id: classId } : { month },
          },
        }),
      )) as CalendarMonth,
    { enabled: yearId !== null },
  );
}

export function useCalendarSuggestions(
  yearId: string | null,
  enabled: boolean,
): Loadable<CalendarSuggestions> {
  const api = useBffClient("staff");
  return useApiQuery(
    SCHOOL_CALENDAR_KEYS.suggestions(yearId ?? ""),
    async () =>
      (await unwrap(
        calendarApi(api).GET(`${YEAR_PATH}/suggestions`, {
          params: { path: { year_id: yearId ?? "" } },
        }),
      )) as CalendarSuggestions,
    { enabled: enabled && yearId !== null },
  );
}

/** `YYYY-MM` of an ISO date. */
export function monthOf(isoDate: string): string {
  return isoDate.slice(0, 7);
}

/** The month before or after `YYYY-MM`. */
export function shiftMonth(month: string, by: number): string {
  const [y, m] = month.split("-").map(Number) as [number, number];
  const index = y * 12 + (m - 1) + by;
  const year = Math.floor(index / 12);
  const mon = (index % 12) + 1;
  return `${year}-${String(mon).padStart(2, "0")}`;
}

/** Monday-first weekday of an ISO date (0 = Monday .. 6 = Sunday), in UTC so no zone shift. */
export function weekdayOf(isoDate: string): number {
  const day = new Date(`${isoDate}T00:00:00Z`).getUTCDay();
  return (day + 6) % 7;
}

/** The ISO date `by` days after `isoDate`. */
export function addDays(isoDate: string, by: number): string {
  const date = new Date(`${isoDate}T00:00:00Z`);
  date.setUTCDate(date.getUTCDate() + by);
  return date.toISOString().slice(0, 10);
}
